"""Complete 28 original acid-base and electrolyte emergency questions."""
from create_critical_acid_base import rows,add,AB,ref
from qbank_authoring import finalize
HY=ref('European multidisciplinary hyponatraemia clinical practice guideline','https://academic.oup.com/ejendo/article/170/3/G1/6668028')
HK=ref('UK Kidney Association hyperkalaemia guideline','https://guidelines.ukkidney.org/hyperkalaemia/')
RC=ref('Resuscitation Council UK special circumstances: 2025','https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines')
CA=ref('Society for Endocrinology acute hypocalcaemia emergency guidance','https://pmc.ncbi.nlm.nih.gov/articles/PMC8117371/')

add('An adult with sodium 112 mmol/L has an ongoing generalized seizure attributed to hypotonic hyponatremia. Which immediate sodium-directed treatment is appropriate?', 'Monitored bolus treatment with 3% saline, aiming initially for a small symptom-relieving sodium rise',[
 ('Fluid restriction alone while awaiting seizure resolution','This is too slow for severe neurological symptoms.'),('Tolvaptan as the initial seizure treatment','Vaptans are not appropriate emergency treatment for this presentation.'),('Rapid normalization to 140 mmol/L with hypertonic saline','The initial goal is relief of cerebral edema, not complete normalization.')],
 'Treat severe symptoms promptly while controlling total correction','**Hypertonic saline is indicated for severe neurological manifestations of hypotonic hyponatremia.**',['A small initial rise can reduce cerebral edema.','Bolus volume follows the adopted protocol, commonly one hundred to one hundred fifty milliliters in adults.'],'**Reassess symptoms and sodium after each bolus.**',['Monitor urine output for emerging water diuresis.','Subsequent correction limits depend on chronicity and osmotic-demylination risk.'],[['Immediate goal','Reverse severe neurological symptoms'],['Initial fluid','3% saline bolus protocol'],['Avoid','Rapid full normalization']],[HY])

add('A malnourished patient with chronic sodium 105 mmol/L is being treated. Which daily correction strategy best reflects the high risk of osmotic demyelination?', 'Use a conservative goal around 4–6 mmol/L and avoid exceeding 8 mmol/L in any 24 hours',[
 ('Target an increase of 16–20 mmol/L in the first day','This creates substantial demyelination risk in a high-risk patient.'),('Allow 12 mmol/L daily provided symptoms have improved','Symptom improvement does not remove the risk from excessive total correction.'),('Do not count potassium replacement toward changes in sodium','Potassium replacement can contribute to the rise in serum sodium.')],
 'A correction limit is not a treatment target','**Very low initial sodium, malnutrition, alcohol-related disease, hypokalemia and advanced liver disease increase risk.**',['Use a safety margin below the maximum permitted rise.','Include all sources of correction and unexpected aquaresis.'],'**Measure sodium frequently and intervene before overshoot.**',['Reassess infusion rates when urine output rises.','Use expert-guided desmopressin and free water when appropriate.'],[['Goal','Modest planned correction'],['High-risk ceiling','No more than 8 mmol/L per 24 h'],['Hidden contributor','Potassium replacement']],[HY])

add('During correction of chronic hyponatremia, sodium rises 11 mmol/L in 8 hours with new high-volume dilute urine. What is the most appropriate response?', 'Stop active correction and urgently consider desmopressin plus electrolyte-free water under close monitoring',[
 ('Continue saline because urine losses make demyelination unlikely','Water diuresis is a common driver of dangerous overcorrection.'),('Add tolvaptan to make the correction more predictable','Further aquaresis can worsen the overshoot.'),('Give a loop diuretic without reassessing the sodium trajectory','Additional free-water loss can increase sodium further.')],
 'The kidney can suddenly become the main sodium-correction driver','**Resolution of antidiuresis can produce rapid aquaresis.**',['Simply stopping saline may not stop ongoing water loss.','Relowering decisions depend on initial sodium, risk and correction magnitude.'],'**Obtain specialist help and monitor sodium and urine output closely.**',['Desmopressin can restrain further water loss.','Dextrose water provides electrolyte-free water after metabolism.'],[['Warning','Rapid rise plus dilute polyuria'],['Brake','Desmopressin when indicated'],['Relowering','Controlled free-water replacement']],[HY])

add('A patient with sodium 118 mmol/L has measured serum osmolality 265 mOsm/kg, urine osmolality 70 mOsm/kg and heavy water intake. Which mechanism is most likely?', 'Excess water intake relative to solute excretion with appropriately suppressed vasopressin',[
 ('Persistent strong vasopressin activity from SIADH','Urine is maximally dilute rather than inappropriately concentrated.'),('Hyperglycemic translocational hyponatremia','Measured osmolality is low and the stem does not show marked hyperglycemia.'),('Pseudohyponatremia from severe hyperlipidemia','That typically has normal measured osmolality without true hypotonicity.')],
 'Urine dilution locates the physiological problem','**Urine osmolality below one hundred suggests effective suppression of antidiuresis.**',['Water intake may exceed the maximum excretory capacity, especially with low solute intake.','A later solute load can abruptly increase water excretion.'],'**Control intake and monitor the correction trajectory.**',['Assess nutritional solute intake and medications.','Beware rapid autocorrection when the precipitating circumstance changes.'],[['Serum','Hypotonic'],['Urine','Very dilute'],['Mechanism','Water load/low-solute capacity rather than persistent antidiuresis']],[HY])

add('After pituitary surgery, sodium is 156 mmol/L with polyuria and urine osmolality 90 mOsm/kg. Glucose is normal. Which diagnosis is most likely?', 'Central arginine-vasopressin deficiency',[
 ('Osmotic diuresis from glucosuria','Glucose is normal and the urine is very dilute rather than solute-rich.'),('SIADH','This causes water retention and usually hyponatremia rather than dilute polyuria with hypernatremia.'),('Cerebral salt wasting','That is a sodium-losing hyponatremic syndrome, not this pattern.')],
 'Inappropriately dilute urine during hypernatremia indicates a water-conservation defect','**Pituitary injury can impair vasopressin secretion.**',['Differentiate central deficiency from renal resistance using the context and response to desmopressin.','Account for simultaneous fluid access, renal function and postoperative changes.'],'**Replace water and manage hormone deficiency with frequent reassessment.**',['Avoid uncontrolled desmopressin dosing that later causes water retention.','The postoperative course can change between water-losing and antidiuretic phases.'],[['Serum sodium','High'],['Urine','Inappropriately dilute'],['Context','Recent pituitary surgery']],[ref('Society for Endocrinology inpatient cranial diabetes insipidus guidance','https://pmc.ncbi.nlm.nih.gov/articles/PMC6013691/')])

add('A 70-kg man has estimated total body water 35 L and sodium 168 mmol/L. Using a target of 140, what is the approximate calculated free-water deficit before ongoing losses?', '7 L',[
 ('3.5 L','This underestimates the stated water deficit formula.'),('14 L','This doubles the calculated value.'),('28 L','This confuses the sodium difference with a water volume.')],
 'The water-deficit formula estimates a starting requirement','**Deficit = total body water × (current sodium/target sodium − 1).**',['Thirty-five times one-point-two minus one equals seven liters.','Total body water estimates and ongoing losses introduce substantial uncertainty.'],'**Use serial sodium measurements to guide actual replacement.**',['Restore circulation with appropriate isotonic fluid first if shock is present.','Correction rate depends on duration and clinical context, not deficit size alone.'],[['Estimated TBW','35 L'],['Sodium ratio','1.2'],['Deficit','7 L before ongoing losses']],[AB])

add('A patient with potassium 7.2 mmol/L develops QRS widening. Which intervention primarily provides immediate cardiac protection rather than potassium removal?', 'Intravenous calcium',[
 ('Intravenous insulin with glucose','This shifts potassium into cells but is not the immediate calcium-mediated cardiac protection step.'),('Hemodialysis','This removes potassium but requires organization and does not replace immediate stabilization.'),('A potassium binder','This facilitates gastrointestinal removal over time rather than immediate ECG protection.')],
 'Separate protection, redistribution and removal','**Calcium can reverse hyperkalemic electrical toxicity without lowering the potassium concentration.**',['Use the correct salt, dose, access and monitoring protocol.','Calcium chloride and gluconate contain different elemental calcium per milliliter.'],'**Begin potassium-shifting and removal treatment in parallel.**',['Repeat ECG assessment and calcium when indicated by the protocol.','Do not let an improved ECG substitute for serial potassium measurement.'],[['Calcium','Immediate cardiac protection'],['Insulin/glucose','Intracellular shift'],['Dialysis','Body potassium removal']],[HK,RC])

add('After insulin–glucose treatment for hyperkalemia, which complication requires scheduled monitoring even after potassium improves?', 'Delayed hypoglycemia',[
 ('Persistent hypercalcemia as the expected insulin effect','Insulin does not routinely cause this biochemical complication.'),('A predictable sustained rise in serum potassium','The immediate insulin effect is intracellular potassium shift; rebound is a separate issue.'),('An isolated prolonged INR','This is not the characteristic insulin–glucose adverse effect.')],
 'The glucose risk outlasts the initial infusion','**Insulin action can persist after administered glucose is consumed.**',['Kidney dysfunction can prolong insulin effects.','Additional glucose support depends on baseline glucose and the local protocol.'],'**Monitor both glucose and potassium over the following hours.**',['A normal immediate glucose does not exclude later hypoglycemia.','Identify a definitive potassium-removal strategy and contributors to recurrence.'],[['Early effect','Potassium redistribution'],['Later risk','Hypoglycemia'],['Follow-up','Scheduled glucose and potassium checks']],[HK])

add('A patient has potassium 2.6 mmol/L despite replacement and magnesium 0.35 mmol/L. Which action is most likely to improve sustained potassium correction?', 'Replace magnesium as well as potassium',[
 ('Increase insulin to drive potassium intracellularly','This aggravates hypokalemia.'),('Restrict magnesium until potassium is normal','Magnesium depletion promotes renal potassium wasting.'),('Replace potassium only as bicarbonate regardless of acid-base state','Salt selection matters; this does not address magnesium-related wasting.')],
 'Potassium and magnesium deficits commonly coexist','**Magnesium depletion can increase renal potassium loss and make replacement refractory.**',['Both deficiencies can increase arrhythmia risk.','Gastrointestinal losses, diuretics and poor intake often contribute.'],'**Correct both deficits with renal-function-aware monitoring.**',['Choose oral or IV routes according to severity and clinical stability.','Assess ongoing losses and ECG changes.'],[['Low magnesium','Persistent potassium wasting'],['Replacement','Both deficits'],['Safety','Rhythm and renal function']],[HK])

add('A patient develops tetany and prolonged QT after thyroid surgery, with low ionized calcium. Which immediate treatment is most appropriate?', 'ECG-monitored intravenous calcium gluconate with subsequent cause-directed replacement',[
 ('Oral calcium alone while tetany persists','Symptomatic severe hypocalcemia requires more immediate correction.'),('Intravenous bicarbonate to increase calcium binding','Alkalinization can further reduce ionized calcium.'),('A loop diuretic to increase urinary calcium loss','This can worsen the deficit and does not address the emergency.')],
 'Symptoms and ionized calcium determine urgency','**Acute hypocalcemia can cause neuromuscular irritability and arrhythmia.**',['Postoperative hypoparathyroidism is a relevant cause.','Assess magnesium because depletion can impair PTH secretion/action.'],'**Correct immediate danger, then plan calcium and active-vitamin-D treatment as indicated.**',['Use monitored administration and repeat biochemistry.','Total calcium can mislead when albumin or pH is abnormal.'],[['Symptoms','Tetany'],['ECG','QT prolongation'],['Initial therapy','Monitored IV calcium']],[CA])

add('During massive transfusion, ionized calcium falls despite a near-normal total calcium concentration. Which mechanism is most likely?', 'Citrate chelation of ionized calcium',[
 ('Immediate vitamin D depletion as the principal mechanism','Vitamin D stores do not change sufficiently fast to explain this acute event.'),('Albumin synthesis suddenly increasing total body calcium','This does not explain acute transfusion-related ionized-calcium loss.'),('Parathyroid adenoma suppression causing hypercalcemia','The biochemical direction and time course do not fit.')],
 'Bound calcium and biologically active calcium are not interchangeable','**Citrate in blood products binds calcium.**',['Rapid delivery and impaired citrate metabolism increase risk.','Ionized calcium is directly relevant to coagulation and myocardial performance.'],'**Monitor ionized calcium during major transfusion and replace as indicated.**',['Follow the major-hemorrhage protocol and avoid blind excessive calcium.','Treat hemorrhage and temperature/coagulation disturbances concurrently.'],[['Exposure','Citrate-containing products'],['Measurement','Ionized calcium'],['Clinical impact','Coagulation and contractility']],[CA,ref('European major trauma bleeding guideline: 2023','https://pmc.ncbi.nlm.nih.gov/articles/PMC9977110/')])

add('An adult has calcium 15.8 mg/dL, dehydration and confusion from hypercalcemia of malignancy. Which approach best addresses immediate and sustained control?', 'Carefully tailored isotonic hydration, a rapid short-course calcitonin bridge and an antiresorptive agent',[
 ('Calcitonin alone as durable treatment for several weeks','Tachyphylaxis limits its short-term bridging role.'),('Routine loop diuresis before correcting intravascular depletion','This can worsen dehydration; loops are reserved for selected fluid-overload situations.'),('Withhold antiresorptive therapy until saline has normalized calcium','Severe malignancy-associated hypercalcemia often needs treatment beyond hydration.')],
 'Bridge rapid control to a sustained mechanism','**Calcitonin works quickly but its effect wanes; antiresorptive treatment takes longer.**',['Choice between denosumab and an IV bisphosphonate considers guideline recommendations and kidney function.','Cardiac and renal disease constrain fluid delivery.'],'**Treat the malignancy and monitor calcium, phosphate and renal function.**',['Avoid a fixed large fluid prescription in every patient.','Check for later hypocalcemia after antiresorptive treatment.'],[['Hydration','Correct volume deficit'],['Calcitonin','Short rapid bridge'],['Antiresorptive','Longer control']],[ref('Endocrine Society hypercalcemia of malignancy guideline','https://www.endocrine.org/clinical-practice-guidelines/hypercalcemia')])

add('A patient with prolonged seizures has severe symptomatic hyponatremia and low potassium. Which statement about potassium replacement is correct?', 'Potassium replacement can itself raise serum sodium and must be included in the correction plan',[
 ('Potassium has no effect on sodium concentration because they are different ions','Serum sodium relates to exchangeable sodium plus potassium relative to body water.'),('Potassium replacement prevents osmotic demyelination regardless of sodium trajectory','Correction risk still depends on the total osmotic change.'),('Potassium should be omitted despite dangerous hypokalemia to simplify sodium management','Both emergencies require coordinated correction rather than ignoring one.')],
 'Treat the electrolyte system rather than isolated numbers','**Retained potassium contributes to effective body cation content.**',['Potassium repletion can increase serum sodium through coupled cellular/water shifts.','Hypokalemia also increases osmotic-demylination risk.'],'**Coordinate hypertonic saline, potassium and water management.**',['Follow frequent sodium and potassium measurements.','Reduce other correction drivers when the combined rise is faster than planned.'],[['Potassium deficit','Needs treatment'],['Sodium effect','Can rise during potassium repletion'],['Plan','Count all correction contributors']],[HY])

add('A patient with severe hypophosphatemia develops ventilatory muscle weakness after prolonged malnutrition. Which mechanism best links the electrolyte disorder to failed weaning?', 'Reduced ATP availability impairing skeletal-muscle function',[
 ('Direct irreversible neuromuscular-junction antibody production','That describes an autoimmune mechanism rather than phosphate depletion.'),('Primary sodium-channel blockade by phosphate','This is not the mechanism of phosphate-depletion weakness.'),('Increased ATP synthesis causing sustained muscle contraction','Phosphate depletion compromises energy availability rather than increasing it.')],
 'Phosphate is an energy and membrane substrate','**Severe depletion can impair diaphragm and other skeletal-muscle performance.**',['Other manifestations include cardiac dysfunction and, in severe cases, rhabdomyolysis or hemolysis.','Redistribution and total-body depletion can coexist.'],'**Replace according to severity, route, renal function and accompanying electrolytes.**',['Monitor calcium and avoid excessive rapid replacement.','Identify refeeding, respiratory alkalosis and renal/GI losses.'],[['Energy','ATP substrate'],['Respiration','Muscle weakness'],['Monitoring','Phosphate, calcium and kidney function']],[ref('ESPEN ICU nutrition practical guideline: 2023','https://doi.org/10.1016/j.clnu.2023.07.011')])

if __name__=='__main__':finalize('Critical Care and Toxicology',4,'Acid-base and Electrolyte Emergencies','critical-electrolytes',rows,28)
